/**
 * An interface declares behaviour that classes can implement. Functions can
 * accept `ref Interface` and dispatch dynamically to the concrete type.
 */
interface Drawable {
  /** Prints a description of this shape through its drawing interface. */
  public method draw() void;
}
/** A drawable circle used to demonstrate interface dispatch. */
class Circle implements Drawable {
  public var radius: f64;
  /** Initializes the fixture fields used by this example or regression test. */
  init(r: f64) {
