using std;
using std.thread;
using std.time;
/**
 * Take the front item, if there is one. The lock is held for exactly as long
 * as this function runs: the guard is released when `g` goes out of scope at
 * the end of it, so the caller can wait without stalling the producer.
 */
function take_one(q: const ref Shared<Queue<i64>>) Option<i64> {
  var g = q.lock();
  return g.get().pop();
}
// The two thread bodies, as lambdas at global scope. Each takes the handle it
// works through as a parameter rather than capturing one: spawn moves its
// arguments into the thread, so the handle is the thread's from the moment it
// starts, and is released when the thread ends. A global lambda captures
// nothing at all — globals are read directly — so the same one can be spawned
// as often as you like.
// Push ten squares onto the queue.
var produce = (q: Shared<Queue<i64>>) => i32 {
  var i: i64 = 1;
  while (i <= 10) {
    // The lock is held just long enough to push: the guard is released at
    // the end of each iteration.
    var g = q.lock();
    g.get().push(i * i);
    i = i + 1;
  }
  return 0;
};
// The consumer knows how many items to expect, so it stops after ten rather
// than needing the producer to tell it when to stop.
var consume = (q: Shared<Queue<i64>>) => i32 {
  var received: i64 = 0;
  var total: i64 = 0;
  while (received < 10) {
    match (take_one(q)) {
      Option.Some(item) => {
        received = received + 1;
        total = total + item;
      },
      // Nothing queued yet. Step aside rather than spin on the lock —
      // take_one released it before returning.
      Option.None => {
        sleep(create_duration_micros(100));
      }
    };
  }
  return _convert<i32>(total);
};
/** Runs the example that coordinates producer and consumer threads. */
function main() i32 {
  var alloc = make_heap_allocator();
  // One queue, two owners. Sun never copies a class implicitly, so each
  // thread needs its own handle, made with an explicit clone().
  var queue = Shared<Queue<i64>>(alloc, Queue<i64>(alloc));
  var producer = spawn(produce, queue.clone());
  var consumer = spawn(consume, queue.clone());
  producer.join();
  var total = consumer.join();
  // Both threads have finished, so the last handle can read without a race.
  var g = queue.lock();
  println(`items left: ${g.get().size()}`);
  println(`total: ${total}`);
  return 0;
}
manifest {
    libraries: ["stdlib.moon"]
}

data._sizeoft#_sizeof<T>():
Returns the byte size of type T as i64.
var size = _sizeof<i32>();   // 4
var size2 = _sizeof<i64>();  // 8
class Point { x: f64; y: f64; }
var pointSize = _sizeof<Point>();  // 16 (two 8-byte floats)

data._inittptr-args#_init<T>(ptr, args...):
Constructs an instance of type T at the memory location pointed to by ptr, forwarding args to the constructor.
// Allocate raw memory for a Point
var mem = unsafe { _malloc(_sizeof<Point>()); };
// Construct Point at that location
unsafe { _init<Point>(mem, 3.0, 4.0); };
// mem now points to an initialized Point
For non-class types, _init is a no-op since primitives don't have constructors.

data._deinittptr#_deinit<T>(ptr):
The counterpart of _init<T>: runs T's deinit on the value at ptr, then
drops any of its fields that own something. For a payload enum it drops through
the active variant. For anything that owns nothing it is a no-op, so a
container can call it on every element without asking what T is.
// Release element i, then reuse its slot
unsafe {
    _deinit<T>(_ptr_as_raw<T>(_ptr_offset(this.data, i * _sizeof<T>())));
};
It releases the value without freeing the storage, which is what a container
that manages its own buffer needs.

data._params_oft#_params_of<T>:
Names the parameter list a value pack stands for. It appears only after the
colon of an args... pack in a parameter list, never as a type of its own:
function make<T>(args...: _params_of<T>) raw_ptr<T> {
    var size: i64 = _sizeof<T>();
    var memory: raw_ptr<i8> = unsafe { _malloc(size); };
    unsafe { _init<T>(memory, args...); };
    return memory;
}
For a class, _params_of<T> is the parameters of T's init — any overload
the call's arguments match, so make<Point>(3, 4) and make<Point>(9) each
select their own. For a lambda, it is the parameters that lambda takes. For
anything else the pack is accepted and left unchecked.See Value Packs for the full rules.

data._return_type_off#_return_type_of<F>:
The type F returns. Like _params_of<T> it is computed rather than named,
but unlike it, it is a type in its own right and goes wherever a type
annotation goes. F must be a lambda or a function type.
public function spawn<F: _Callable>(fn: F, args...: _params_of<F>)
    Thread<_return_type_of<F>> {
    return Thread<_return_type_of<F>>(unsafe { _spawn<F>(fn, args...); });
}
Inside the template it stays symbolic — nothing can say what F returns until
a call says what F is — and it is resolved when the call is specialized.

data._loadtptr-index#_load<T>(ptr, index):
Loads an element of type T from ptr at the given element index. Equivalent to ptr[index] in C.
// Assuming data points to an array of i32
var value = unsafe { _load<i32>(data, 5); };  // Load data[5]

data._storetptr-index-value#_store<T>(ptr, in:
Stores value of type T at ptr[index].
// Store 42 at data[5]
unsafe { _store<i32>(data, 5, 42); };

data._ptr_as_rawtptrt#_ptr_as_raw<T>(ptr<T>):
Converts an owning ptr<T> to a non-owning raw_ptr<T> without transferring ownership. Similar to C++'s unique_ptr::get().
var owned: ptr<Point> = new Point(1.0, 2.0);
var raw: raw_ptr<Point> = _ptr_as_raw<Point>(owned);
// raw points to the same memory, but owned still manages lifetime
Be careful: the raw pointer becomes invalid if the owning pointer is freed or goes out of scope.

data.use-in-generic-code#Use in Generic Code:
_is<T> is particularly useful in generic functions to branch based on type:
function processValue<T>(x: T) i32 {
    if (_is<_Integer>(x)) {
        // Integer-specific logic
        return 1;
    }
    if (_is<_Float>(x)) {
        // Float-specific logic
        return 2;
    }
    return 0;
}
function main() i32 {
    var a = processValue<i32>(42);    // Returns 1
    var b = processValue<f64>(3.14);  // Returns 2
    return a + b;  // 3
}
Since Sun uses monomorphization, each instantiation of processValue compiles to code with the dead branches eliminated by LLVM.

data.interface-checks#Interface Checks:
For class types, _is<T> can check interface implementation:
interface IHashable {
    method hash() i64;
}
class MyKey implements IHashable {
    method hash() i64 { return 42; }
}
function example(key: MyKey) bool {
    return _is<IHashable>(key);  // true
}

data._bitcasttvalue#_bitcast<T>(value):
Reinterprets the bits of a numeric value as another numeric type of the same
size — f32 ↔ u32/i32, f64 ↔ u64/i64. The sizes must match, which is
checked at compile time. Used by binary wire formats to read and write floats.
var bits: u64 = _bitcast<u64>(1.0);   // 0x3FF0000000000000
var back: f64 = _bitcast<f64>(bits);  // 1.0
It also retypes a raw pointer — raw_ptr<A> to raw_ptr<B>, the cast C writes
as (B*)p. This is how a pointer to anything reaches a C function that takes
void*, which Sun declares as raw_ptr<u8>, and how a byte buffer is read as a
header:
extern "C" function c_send(fd: i32, buf: raw_ptr<u8>, n: i64, flags: i32) i64 as "send";
packed_class Header {
    var kind: u16;
    var length: u16;
    init(k: u16, n: u16) { this.kind = k; this.length = n; }
}
function send_header(fd: i32, h: ref Header) i64 {
    var bytes = _bitcast<raw_ptr<u8>>(_address_of<Header>(h));
    unsafe { return c_send(fd, bytes, _sizeof<Header>(), 0); };
}
A bitcast is numeric to numeric or pointer to pointer, never one to the other,
and never to or from a class, enum or interface. Retyping a pointer only renames
it: reading through the result still needs an unsafe block, and it is on you to
have pointed at bytes that really are a B.

data._freeptr#_free(ptr):
Frees memory previously allocated with _malloc. Direct wrapper around C's free. Only usable inside an unsafe block.
var mem = unsafe { _malloc(1024); };
// ... use memory ...
unsafe { _free(mem); };

data._memcpydst-src-len-_memmovedst-src-len-a:
Use _memmove when the source and destination may overlap, such as when compacting a buffer. Like _memcpy, it requires an unsafe block and valid memory ranges. It performs no allocation._memcpy and _memmove copy len bytes from src to dst; _memset sets
len bytes at dst to a single byte value. They take raw pointers and a byte
count and lower to LLVM memory intrinsics. Only _memcpy requires the source
and destination regions not to overlap.
// Grow a buffer: move the old bytes across, then zero the new tail
unsafe {
    _memcpy(newData, oldData, this.len * _sizeof<T>());
    _memset(_ptr_offset(newData, this.len * _sizeof<T>()), 0, added);
};
These move bytes, not values. Copying a compound value this way would leave two
owners of one buffer — see Memory Safety.

data._to_reftraw_ptrt#_to_ref<T>(raw_ptr<T>):
The reverse of _address_of: turns a raw_ptr<T> into a ref T so the
pointed-to value can be read, borrowed or assigned through like any reference.
Nothing checks that the pointer is non-null or still points at a live T, so
write it inside unsafe { } — the standard library does so at every use. The
borrow checker gives the reference the lifetime of the pointer, so the pointer
must stay valid for as long as the reference is used.
var x: i32 = 1;
var p: raw_ptr<i32> = _address_of<i32>(x);
var r: ref i32 = unsafe { _to_ref<i32>(p); };
r = 2;   // x is now 2

data._atomic_cmpxchg_i32i64u64ptr-expected-de:
Atomically compares the value at ptr with expected. If they are equal, it
stores desired. The return value is always the value that was at ptr, so the
exchange succeeded when the return value equals expected.
var state: i32 = 0;
var old = unsafe {
    _atomic_cmpxchg_i32(_address_of<i32>(state), 0, 1);
};

data._atomic_store_i32i64u64ptr-value#_atomic:
Stores value with release ordering.
var sequence: u64 = 0;
var next: u64 = 42;
unsafe { _atomic_store_u64(_address_of<u64>(sequence), next); };

data._atomic_load_i32i64u64ptr#_atomic_load_i:
Loads the value with acquire ordering.
var current = unsafe {
    _atomic_load_u64(_address_of<u64>(sequence));
};

data._atomic_fetch_add_i32i64u64--_atomic_fet:
Atomically adds or subtracts delta with acquire-release ordering and returns
the value from before the operation. That is what a reference count needs:
whoever reads 1 from a decrement was the last owner, so exactly one caller runs
the cleanup.
var delta: u64 = 1;
var before = unsafe {
    _atomic_fetch_add_u64(_address_of<u64>(sequence), delta);
};

data._mul_hi_u64a-b#_mul_hi_u64(a, b):
The high 64 bits of the 128-bit product a * b (the low 64 bits are just a * b).
var lo: u64 = a * b;
var hi: u64 = _mul_hi_u64(a, b);

data._target_isos#_target_is(os):
A compile-time check of the operating system being compiled for. The
argument must be a string literal from "linux", "macos" or "windows"
(anything else is a compile error), and the call folds to a constant for the
--target in effect (the host's OS when compiling natively).A branch on a folded condition keeps only its live side — dead branches are
pruned during code generation, not left to an optimizer — so per-OS code may
call C symbols the other systems' libraries lack:
var CLOCK_MONOTONIC: i32 = _target_is("macos") ? 6 : 1;
if (_target_is("macos")) {
    // only ever compiled into macOS binaries
}
For whole files of per-OS definitions, prefer the manifest's target: block
(see Modules); _target_is is the in-function form of the same
vocabulary.

data.usage-in-standard-library#Usage in Stand:
The standard library uses intrinsics to implement generic containers. Here's a simplified example of how Vec<T> might use them:
class Vec<T> {
    data: raw_ptr<i8>;
    len: i64;
    cap: i64;
    alloc: HeapAllocator;
    method get(index: i64) T {
        return unsafe { _load<T>(this.data, index); };
    }
    method set(index: i64, value: T) void {
        unsafe { _store<T>(this.data, index, value); };
    }
    method push(value: T) void {
        if (this.len >= this.cap) {
            this.grow();
        }
        unsafe { _store<T>(this.data, this.len, value); };
        this.len = this.len + 1;
    }
    method grow() void {
        var newCap = this.cap * 2;
        var newData = this.alloc.alloc_raw(newCap * _sizeof<T>());
        unsafe {
            _memcpy(newData, this.data, this.len * _sizeof<T>());
            _free(this.data);
        };
        this.data = newData;
        this.cap = newCap;
    }
}

data:
Sun imports Protocol Buffer schemas natively: list .proto files in the
manifest and the compiler synthesizes ordinary Sun classes for every message,
with monomorphic encode/decode that speak the standard wire format. There
are no generated source files to check in, no runtime reflection, and no
libprotobuf dependency in the compiled program.
manifest {
    protos: ["schemas/telemetry.proto"]
    libraries: ["stdlib.moon"]
}
using std;
using namo.telemetry;      // the proto `package`
function main() i32 {
    var alloc = make_heap_allocator();
    var status = RobotStatus(alloc);      // zero-value init (proto3 defaults)
    status.robot_id = 7;
    status.name = String(alloc, "rover");
    status.samples.push(300);
    status.mode = Mode.FAULT;
    var buf = Vec<u8>(alloc, 64);
    status.encode(buf);                   // appends wire bytes
    try {
        var back = RobotStatus_decode(alloc, buf);
        return back.robot_id;
    } catch (e: IError) {
        return -1;                        // malformed input throws
    }
}
syntax = "proto3";
package namo.telemetry;
enum Mode { IDLE = 0; ACTIVE = 1; FAULT = 7; }
message Pose { double x = 1; double y = 2; }
message RobotStatus {
  int32 robot_id = 1;
  string name = 2;
  repeated int64 samples = 3;
  Mode mode = 4;
  Pose pose = 5;
  optional string nickname = 6;
  oneof power { int32 battery_pct = 7; string station_id = 8; }
  map<string, int32> scores = 9;
}
Schemas are parsed at compile time with the protobuf compiler library
(libprotoc); paths resolve like other manifest entries — relative to the
entrypoint, then through SUN_PATH — and proto-level import statements
resolve the same way. Run sun --dump-proto-sun main.sun to print the Sun
source the compiler synthesized.

data.ownership#Ownership:
Message classes follow the language's ownership rules — see
Memory Safety. Fields hold their values, Vec/Map/String fields
own their contents, and assigning a compound field moves the source. Match
bindings over optional and oneof payloads borrow in place:
match status.nickname {
    Option.Some(s) => println(s.length()),   // s borrows the String
    Option.None => { }
};
match status.power {
    RobotStatus_power.BatteryPct(pct) => { },
    RobotStatus_power.StationId(id) => { },
    RobotStatus_power.NotSet => { }
};
status.power = RobotStatus_power.BatteryPct(80);   // drops the old payload

data.classes#Classes:
Classes are value types that use move semantics. When you assign a class instance to another variable, ownership is transferred and the original variable becomes invalid:
class Point {
    var x: i32;
    var y: i32;

    init(px: i32, py: i32) {
        this.x = px;
        this.y = py;
    }
}
function main() i32 {
    var p1 = Point(3, 4);  // p1 owns the Point
    var p2 = p1;           // Ownership moves to p2

    // p1.x;               // ❌ ERROR: use of moved value 'p1'
    return p2.x;           // ✓ OK: p2 now owns the Point
}
Error:
error: use of moved variable 'p1'. Ownership was transferred in a previous assignment.
This prevents use-after-move bugs at compile time.

data.writing-to-a-field#Writing to a Field:
Assigning to a field moves the new value in and drops the value the field held
before, so the old one is released exactly once. A constructor's first write to
a field is the exception: the field has never held a value at that point, so
there is nothing to release and nothing is dropped.
class Holder {
    var res: Res;
    init() {
        this.res = Res(1);   // starts the field's life — nothing dropped
    }
    method replace(r: Res) void {
        this.res = r;        // replaces what the field holds, dropping it
    }
}
In a constructor every write to an owning field has to be one of those two,
and the compiler has to be sure which. A second write is fine when the field
certainly holds a value by then, because what it replaces is known:
init() {
    this.res = Res(1);   // starts its life
    this.res = Res(2);   // certainly replaces Res(1), which is dropped
}
What is rejected is a write the compiler cannot place — where some path
reaching it assigned the field and some did not:
init(flag: bool) {
    if (flag) { this.res = Res(1); }
    this.res = Res(2);   // ❌ did the branch already assign it?
}
Branches are alternatives, so one assignment in each is still one assignment,
and every path arrives in the same state:
init(flag: bool) {
    if (flag) { this.res = Res(1); } else { this.res = Res(2); }
}
A try block asks it too: a throw can leave the block part-way through, so a
catch clause cannot tell whether the field was assigned before the throw.A loop is the same question: its body may be the first pass or a later one, so
it needs the field settled before the loop, or the value settled in a local and
assigned once.
init(n: i32) {
    var chosen = Res(0);
    for (var i: i32 = 1; i < n; i = i + 1) { chosen = Res(i); }
    this.res = chosen;   // one assignment, whatever the loop did
}
Only fields that own something are held to this. A field holding a number
releases nothing when it is written again, so accumulating a total in a loop is
fine.A constructor's first direct assignment starts a field's lifetime without
destroying its storage. Later assignments destroy the previous value, unless
ownership has moved away.

data.returning-classes-from-functions#Returni:
Functions can return class instances, transferring ownership to the caller:
function create_point(x: i32, y: i32) Point {
    return Point(x, y);  // Ownership transfers to caller
}
function main() i32 {
    var p = create_point(5, 10);
    return p.x + p.y;  // Returns 15
}
The caller owns the result even when it ignores it. A call used as a
statement (create_point(1, 2);) produces a temporary that nobody takes,
and it is dropped — its deinit runs — at the end of the enclosing scope,
the same as a discarded constructor temporary.

data.constants#Constants:
A binding declared with const instead of var never changes: it cannot be
assigned to (=, +=), none of its fields or elements can be assigned, no
field can be moved out of it, nothing may take a mutable ref to it, and only
const methods may be called on it. It can be read,
borrowed with const ref, copied if it is a scalar, and — for a local — moved
as a whole, which ends the binding.
const LIMIT: i32 = 100;           // a constant global
function main() i32 {
    const p = Point(3, 4);
    const n = p.x + LIMIT;        // ✓ reads are fine
    var q = p;                    // ✓ a whole-value move ends `p`
    // p.x = 5;                   // ❌ ERROR: cannot assign to field 'x' of constant 'p'
    // LIMIT = 1;                 // ❌ ERROR: cannot assign to constant 'LIMIT'
    return n;
}
A constant global is initialised at runtime like any other global; compile-time
evaluation is on the roadmap. for (const x: T in c) makes the loop binding
constant for each element.

data.references#References:
References provide temporary, scoped access to variables without transferring ownership. Create a reference using the ref keyword:
function main() i32 {
    var x: i32 = 42;
    ref r = x;      // r references x (mutable borrow)
    r = 100;        // Modifying through r changes x
    return x;       // Returns 100
}
References allow you to access and modify variables without copying or moving:
function increment(x: ref i32) void {
    x = x + 1;
}
function main() i32 {
    var count: i32 = 0;
    increment(count);  // count is now 1
    increment(count);  // count is now 2
    return count;      // Returns 2
}
A declaration annotated ref T borrows too, which is what lets a borrow carry
an explicit type or come from a call that returns one:
function main() i32 {
    var p = Point(1, 2);
    var r: ref i32 = p.x;   // borrows the field, same as `ref r = p.x`
    r = 5;
    return p.x;             // Returns 5
}
Either form may pick its target with a conditional, as long as both branches
are themselves borrowable. The reference binds whichever slot the condition
selects, and both objects count as borrowed for its lifetime:
var pick: ref String = h.flag ? h.a : h.b;
The target must have storage: a temporary (var r: ref String = String(alloc,
"x")) is rejected, since the value it borrows would die at the end of the
statement.

data.constant-references#Constant References:
const ref borrows a value for reading only. The statement form is
const ref r = x;, the type is const ref T, and either may bind a
constant, a variable, or a field:
function total(v: const ref Vec<i32>) i64 {
    return v.size();              // ✓ size() is a const method
    // v.push(1);                 // ❌ ERROR: cannot call non-const method 'push'
}
function main() i32 {
    var x: i32 = 1;
    const ref r = x;              // shared borrow: x may still be read and assigned
    var s: const ref i32 = x;     // same, with an annotation
    // r = 2;                     // ❌ ERROR: cannot assign through const reference 'r'
    return r + s;
}
Assigning to x while it is shared-borrowed is fine for a scalar like this
one; a borrowed compound value cannot be replaced at all — see
Rule 4.Through a const ref nothing can be assigned, no mutable ref can be taken,
and only const methods can be called. A ref T may be passed or rebound as
const ref T, never the other way round. When a const method returns a borrow
and the receiver is constant or a const ref, the result is the const view
of the declared type: get(i) ref T yields const ref T, and first()
Option<ref T> yields Option<const ref T>, so a match on it binds a
read-only element.Several const refs to one value may be alive at once; a mutable ref cannot
coexist with any of them.

data.reference-rebinding#Reference Rebinding:
You can create a reference from another reference. The borrow kind may be downgraded (ref to const ref) but never upgraded:
function main() i32 {
    var x: i32 = 10;
    ref r1 = x;       // Mutable borrow of x
    ref r2 = r1;      // ❌ ERROR: x is already borrowed
    const ref r3 = r1;  // ✓ OK: downgrade to a shared borrow
    return x;
}

data.rule-1-single-mutable-borrow#Rule 1: Sin:
At any program point, a variable can have at most one mutable borrow:
function main() i32 {
    var x: i32 = 10;
    ref r1 = x;
    ref r2 = x;  // ❌ ERROR: x is already borrowed
    return r1;
}
Error:
error: cannot borrow 'x' as mutable because it is already borrowed
The borrow checker tracks this via the BorrowState.addBorrow() method, which checks for conflicting active loans before allowing a new borrow.

data.rule-2-sequential-borrows-are-allowed#Ru:
When a reference goes out of scope, the borrow ends. You can then create a new reference:
function main() i32 {
    var x: i32 = 10;

    if (true) {
        ref r1 = x;
        r1 = 20;
    }  // r1 goes out of scope, borrow ends

    ref r2 = x;  // ✓ OK: x is no longer borrowed
    r2 = 30;
    return x;    // Returns 30
}
This works because exitScope() marks loans as inactive when their defining scope ends.

data.rule-3-a-returned-reference-borrows-the-:
A function may return a reference, but only one that lives in something the
caller passed in — a ref parameter, or the receiver of a method. Which
input it points into is not knowable at the call site, so binding the result
to a name conservatively borrows every variable the call could hand back
a reference into:
function longest(a: ref String, b: ref String) ref String {
    if (a.length() > b.length()) { return a; } else { return b; }
}
function main() void {
    var a: String = `.`;
    var b: String = `..`;
    var c: ref String = longest(a, b);  // both a and b are borrowed
    // a = `x`;                         // ❌ ERROR: 'a' is borrowed
    // b = `y`;                         // ❌ ERROR: 'b' is borrowed
    c = `z`;                            // ✓ replaces whichever c points at
    println(c);
}
The same applies to container accessors: var e: ref T = vec.get(i) borrows
vec until e goes out of scope. When you only need the value of a scalar
element, annotate the scalar type instead — var e: i32 = vec.get(i) copies
it out and takes no borrow.

data.rule-4-a-borrowed-compound-value-cannot-:
Assigning a new value to a class, payload enum, or interface variable drops
the old value — including the storage every live borrow points into. So while
such a variable is borrowed, assigning to it is rejected; assign through
the borrow instead, which correctly drops the old referent and moves the new
value in:
function main() void {
    var b: String = `..`;
    var c: ref String = b;
    // b = `new`;    // ❌ ERROR: cannot assign to 'b' because it is borrowed
    c = `new`;       // ✓ replaces b through the borrow
}
Scalars are different: overwriting an i32 leaves its storage in place, so
assigning to a borrowed scalar stays legal and live borrows simply observe
the new value:
function main() i32 {
    var x: i32 = 10;
    ref r = x;
    x = 20;      // ✓ scalar write; nothing is dropped
    return r;    // Returns 20
}

data.rule-5-a-class-that-stores-references-is:
A class may have reference-type fields. Such a value points into storage it
does not own, so it is treated like a borrow: constructing it takes a loan on
every variable passed by ref to the constructor, and those loans last until
the enclosing scope ends. The value must also never be held by a variable
declared in an outer scope than what it borrows — the holder would keep the
borrowed storage's address past its death:
var a = Inner(1);
var h = Holder(a);       // ✓ h and a live equally long
if (true) {
    var b = Inner(2);
    h = Holder(b);       // ❌ ERROR: h outlives b, the stored ref would dangle
}
The bound follows the value when it moves: a holder built in an inner scope
may move outward exactly as far as the outermost variable it borrows.
class Holder {
    public var x: ref String;
    init(x: ref String) { this.x = x; }
}
function main() void {
    var a: String = `a`;
    var b: String = `b`;
    var t = Holder(a);   // t stores a ref into a: a is borrowed
    // b = a;            // ❌ ERROR: cannot move out of 'a' because it is borrowed
    // ref r = a;        // ❌ ERROR: 'a' is already borrowed
    println(t.x);        // ✓ reads through the stored ref
}
And like a lambda with a capture list, such a value cannot leave the frame
that built it — what its refs point into dies when the function returns:
function make() Holder {
    var a: String = `dies here`;
    return Holder(a);   // ❌ ERROR: cannot return a value that stores references
}
This holds transitively: a class whose field is (or contains) a ref-storing
class is subject to the same rules.

data.an-unsized-array-is-a-view#An Unsized Ar:
A sized array<T, N> owns its elements and moves like any other compound
value. An unsized array<T> owns nothing: it is a view of some sized array
with its rank erased, and it may only be written behind ref. A
ref array<T> parameter borrows the array it is given; a ref array<T> field
is a reference field, so the class is a holder under Rule 5; a
ref array<T> return is a reference return under Rule 3.
class Holder {
    var xs: const ref array<i64>;                     // a view: Holder is a holder
    init(xs: const ref array<i64>) { this.xs = xs; }
}
function make() Holder {
    var local: array<i64, 3> = [10, 20, 30];
    return Holder(local);   // ❌ ERROR: cannot return a value that stores references
}
function first(xs: const ref array<i64>) array<i64> {   // ❌ ERROR: array<T> may only
    return xs;                                          //    be used behind ref
}
function main() i32 {
    var a: array<i64, 3> = [10, 20, 30];
    var h = Holder(a);       // ✓ h borrows a until the end of main
    var b = a;               // ❌ ERROR: cannot move out of 'a' because it is borrowed
    return 0;
}

data.rule-5b-an-anonymous-lambda-lifetime-is-:
A lambda that carries a captured environment — a [ref x] or owned [x]
capture list, or a bound method holding its receiver — has the type
<'_>(…) => …, while a plain (…) => … annotation admits only
environment-free lambdas (an environment-free lambda widens into a <'_>
parameter, never the reverse). Because the type says the value may point into
a stack frame, the compiler bars it from everything that outlives one:
function make() <'_>() => i32 { ... }   // ❌ ERROR: <'_> cannot be a return type
var g: <'_>() => i32 = ...;             // ❌ ERROR: a global would outlive the frame
The property is transitive, exactly like Rule 5: a class with a <'_>
field, an enum with a <'_> payload, or a container instantiated over a
<'_> lambda type (Vec<<'_>() => i32>) is frame-bound as a whole — it
works freely inside the frame, but cannot be returned, become a global, or
convert to an interface (which would erase the marker from the type).'_ is a fresh anonymous lifetime, unrelated to every other position in
the signature. At a call, the checker therefore makes no guess that an
anonymous callback might flow into a receiver or ref argument. Inside the
callee, the same lack of a relationship means the callback cannot be stored
into storage that may outlive the call:
class Bus {
    var cb: <'_>() => i32;
    public method invoke(cb: <'_>() => i32) i32 {
        return cb();       // ✓ calling does not retain the callback
    }
    public method badSubscribe(cb: <'_>() => i32) void {
        this.cb = cb;      // ❌ nothing says cb outlives this object
    }
    public method subscribe(cb: <'this>() => i32) void {
        this.cb = cb;      // ✓ the signature promises cb outlives this
    }
}
An anonymous callback may still be assigned to a local declared in the same or
a narrower scope, or forwarded to another anonymous callback parameter. Those
destinations cannot outlive the call. A storing free function names both the
callback and destination with the same declared lifetime; a storing member
usually uses 'this.Within one frame, the destination must also not be declared in an outer
scope than the environment — an inner scope's locals die at its closing
brace, while the destination lives on:
var bus = Bus();
if (true) {
    var n = Node();
    bus.subscribe(n.onMsg);   // ❌ ERROR: bus outlives n
}
// ✓ legal when bus and n are declared in the same scope
Two names declared in the same scope are not ordered by this rule: they
drop in reverse declaration order at the scope's end, and the checker does
not chase which of two siblings dies first. Keep a callback and its bus in
the order that lets the bus drop first, or drop the bus explicitly.

data.named-lifetimes-relate-two-positions-of-:
The rules above stop at a function boundary: a helper that stores one
argument into another is invisible at its call sites. A lifetime name
makes the entanglement part of the signature, so every call is checked
against the arguments' real scopes. Lifetimes are declared in the angle
brackets with a leading apostrophe (function wire<'a>, class Bus<'a>);
inside class and interface members the builtin 'this names the receiver's
lifetime and needs no declaration:
class Bus<'a> {
    var cb: <'a>(i32) => i32;    // stored callbacks must outlive 'a
    public method subscribe(cb: <'a>(i32) => i32) void { this.cb = cb; }
    public method publish(x: i32) i32 { var f = this.cb; return f(x); }
}
class Node {
    public method onMsg(x: i32) i32 { ... }
    /* Bus<'this> binds the bus's slot to this node's lifetime: the bus may
       only store things this node outlives */
    public method attach(bus: ref Bus<'this>) void {
        bus.subscribe(this.onMsg);   // ✓ the signature carries the proof
    }
}
var bus = Bus();
if (true) {
    var n = Node();
    n.attach(bus);      // ❌ ERROR: n dies before bus, and attach's
}                       //    signature says the bus may keep n's method
bus.publish(1);
Call sites never write lifetime arguments — the compiler binds each name to
the concrete scopes of the arguments and requires every environment flowing
into a name to outlive every destination sharing it. A callee, in turn, may
only store a named parameter where the destination's declared lifetime is
the same name (its own class's declared lifetimes count for fields of
this), so one caller lifetime can never launder into another. Interfaces
state the same contracts, and an implementing class must repeat the
interface's names exactly. Each <'_> occurrence remains unrelated to the others; only a repeated
declared name creates a relationship. An anonymous return stays banned because
it names no input frame.Some values are frame-bound without their type showing it: the handle
spawn returns for a thread over a capture-list lambda hides that lambda
behind runtime storage. Such a value is tracked per frame instead, and since
a callee cannot be checked against what its parameter type does not say, a
frame-bound value may not be passed to any by-value parameter — nor
stored in a field, an indexed slot, or a global. Pass it by ref, or give
the lambda its data as spawn arguments instead of captures (see
Threads).

data.scope-based-borrowing#Scope-Based Borrow:
Borrows are automatically invalidated when the reference goes out of scope:
function main() i32 {
    var x: i32 = 10;

    if (condition) {
        ref r = x;    // Borrow starts (scope depth increases)
        r = 20;
    }                 // Borrow ends (scope depth decreases)

    x = 30;           // ✓ OK: x is no longer borrowed
    return x;
}
This works naturally with loops - each iteration creates a fresh borrow:
function main() i32 {
    var sum: i32 = 0;
    var i: i32 = 0;

    while (i < 5) {
        ref r = sum;  // New borrow each iteration
        r = r + i;
        i = i + 1;
    }                 // Borrow ends each iteration

    return sum;       // Returns 10 (0+1+2+3+4)
}

data.passing-references-to-functions#Passing:
References can be passed to functions that accept ref parameters:
function swap(a: ref i32, b: ref i32) void {
    var temp: i32 = a;
    a = b;
    b = temp;
}
function main() i32 {
    var x: i32 = 1;
    var y: i32 = 2;
    swap(x, y);
    // x is now 2, y is now 1
    return x;
}
When you pass a variable to a function expecting a ref parameter, the borrow lasts only for the duration of the function call.

data.1-loan-creation#1. Loan Creation:
When ref r = x is encountered:
Resolve target: If x is itself a reference, follow the chain to find the actual borrowed variable
Check conflicts: Query BorrowState for active loans on the target variable
Record loan: If allowed, create a Loan record with the current scope depth
// Simplified from borrow_state.cpp
BorrowCheckResult BorrowState::addBorrow(const std::string& borrowedVar,
                                         const std::string& refName,
                                         BorrowKind kind,
                                         size_t scopeDepth,
                                         const SourceLoc& loc) {
  auto& varLoans = loans_[borrowedVar];

  // Check existing borrows
  for (const auto& loan : varLoans) {
    if (!loan.isActive) continue;

    if (kind == BorrowKind::Mutable) {
      // Mutable borrow requires no existing borrows
      return BorrowCheckResult::error(
          "cannot borrow '" + borrowedVar + "' as mutable because it is already borrowed",
          loan);
    }
  }

  // Create the loan
  varLoans.push_back(Loan(borrowedVar, refName, kind, scopeDepth, loc));
  return BorrowCheckResult::ok();
}

data.2-scope-exit#2. Scope Exit:
When leaving a scope (e.g., end of if block, loop iteration, function):
void BorrowState::exitScope(size_t scopeDepth) {
  for (auto& [var, varLoans] : loans_) {
    for (auto& loan : varLoans) {
      if (loan.isActive && loan.scopeDepth >= scopeDepth) {
        loan.isActive = false;  // Invalidate the loan
      }
    }
  }
}

data.3-move-tracking#3. Move Tracking:
When assigning a class-typed variable:
void BorrowChecker::checkVariableCreation(const VariableCreationAST& var) {
  if (var.get_value() && 
      var.get_value()->getType() == ASTNodeType::VARIABLE_REFERENCE) {
    const auto& srcRef = static_cast<const VariableReferenceAST&>(*var.get_value());
    auto srcType = var.get_value()->getResolvedType();

    if (srcType && srcType->isClass()) {
      movedVariables_.insert(srcRef.getName());  // Mark as moved
    }
  }
}

data.do-use-references-for-in-place-modificat:
function double_array(arr: ref matrix<i32, 10>) void {
    for (var i: i32 = 0; i < 10; i = i + 1) {
        arr[i] = arr[i] * 2;
    }
}

data.do-keep-borrows-short-lived#Do: Keep Bor:
function process(data: ref i32) void {
    // Use data immediately
    var result = data * 2;
    // Don't hold onto the reference longer than needed
}

data.do-use-scopes-to-control-borrow-lifetime:
function main() i32 {
    var x: i32 = 0;

    // Scope limits the borrow
    if (true) {
        ref r = x;
        r = 42;
    }

    // x is free to use again
    return x;
}

data.dont-store-references-when-a-value-will-:
A class with ref fields borrows whatever it was built from, which locks
those variables for the object's whole scope and keeps the object from being
returned. Store the value unless you really want a view:
// Locks its constructor argument for the scope, cannot be returned
class Cache {
    var cached: ref i32;
}
// ✓ Owns its data, moves freely
class Cache {
    var cached: i32;
}

data.dont-use-variables-after-moving#Don't: U:
// ❌ This won't compile
function main() i32 {
    var p1 = Point(1, 2);
    var p2 = p1;
    return p1.x;  // Error: p1 was moved
}
// ✓ Use the new owner
function main() i32 {
    var p1 = Point(1, 2);
    var p2 = p1;
    return p2.x;  // OK: p2 owns the value
}

data:
Sun has builtin unit testing: declare tests with test_function, assert with
std.test, and the compiler produces a test runner for you. Tests never
appear in production binaries or .moon bundles.
using std;
module geometry {
    function addOne(n: i32) i32 {
        return n + 1;
    }
    test_function addsOne() {
        std.test.assert_eq(geometry.addOne(1), 2);
    }
}
function main() i32 {
    return 0;
}
manifest { libraries: ["stdlib.moon"] }
$ sun test program.sun
PASS geometry.addsOne
1 passed, 0 failed

data.fixtures#Fixtures:
Sun needs no fixture framework: a fixture is an ordinary class whose init
does the setup and whose deinit does the teardown.
using std;
module config {
    class TempDir {
        public var path: String;
        init() throws IError { /* create a unique directory */ }
        deinit() { /* remove it and its contents */ }
    }
    test_function writesConfigFile() {
        var dir = config.TempDir();   // setup
        // ... exercise code that writes into dir.path ...
        std.test.assert(true);
        // teardown: dir.deinit() runs here — or during unwinding
        // if an assertion threw
    }
}
Two language guarantees make this complete:
A local is dropped exactly once at the end of its scope, so teardown
always runs after a passing test.
A failed assertion is a throw, and unwinding runs the same drop glue as
scope exit — so teardown also runs when the test fails. What other
frameworks build tearDown() machinery for, Sun's ownership model already
guarantees.
This composes: a test can hold several fixtures (var db = TestDb(); var dir
= TempDir();), and a fallible setup is just init() throws IError — a setup
failure is reported through the same path as an assertion.

data:
The Sun standard library is distributed as a precompiled stdlib.moon file. Include it in your manifest and import the std namespace:
using std;
function main() void {
    var allocator = make_heap_allocator();
    // Use stdlib types...
}
manifest {
    libraries: ["stdlib.moon"]
}
An installed compiler finds stdlib.moon on its own — the Homebrew and Debian
packages put it where the compiler already looks. SUN_PATH is only needed
when you built from source, where it points at the build/ directory:
export SUN_PATH=/path/to/sun/build. See
Path Resolution for every place that is searched.
The library's own tests are Sun code: each stdlib/<area>_tests.sun sits
next to the file it tests, listed under test_files: in the manifest (see
Testing). They compile only into the test binary, never into
stdlib.moon.

data.heapallocator#HeapAllocator:
The standard memory allocator using system malloc/free. Many stdlib types require an allocator for construction.
var allocator = make_heap_allocator();
Method	Signature	Description	alloc<T>(count)	(i64) raw_ptr<T>	Allocate array of count elements	alloc_raw(size)	(i64) raw_ptr<i8>	Allocate size raw bytes	dealloc(ptr, size)	(raw_ptr<i8>, i64) void	Free allocated memory	create<T>(args...)	(...) raw_ptr<T>	Allocate and construct a single T	copy()	() HeapAllocator	Create a copy of the allocator	
var allocator = make_heap_allocator();
var p: raw_ptr<Point> = allocator.create<Point>(3, 4);
// p points to a heap-allocated, initialized Point
_free(p);  // Manual cleanup

data.uniquet#Unique<T>:
A smart pointer that automatically frees its data when deinit is called (at scope exit). Provides safe access to heap-allocated objects without manual unsafe blocks.
var allocator = make_heap_allocator();
var p = Unique<Point>(allocator.create<Point>(3, 4));
p.get().x;     // Safe access - returns ref T
p.get_raw();   // Get raw pointer for low-level operations
p.is_null();   // Check if null
// p.deinit() called automatically at scope exit
Method	Signature	Description	get()	() ref T	Safe dereference - returns a reference to the value	get_raw()	() raw_ptr<T>	Get the underlying raw pointer	is_null()	() bool	Check if pointer is null	deinit()	() void	Free memory (called automatically)

data.vect#Vec<T>:
A generic growable array backed by contiguous memory. Implements IIterable<T, Vec<T>> for use with for-in loops.
var allocator = make_heap_allocator();
var v = Vec<i32>(allocator, 8);  // Initial capacity 8
v.push(10);
v.push(20);
v.push(30);
var val = v.get(0);       // 10
v.set(1, 25);             // Update index 1
var last = v.pop();       // Option.Some(30) (removes last element)
var len = v.size();       // 2
